  uri         = aws_lambda_function.list_tasks.invoke_arn
}

# GET /tasks/{id} (Get)
resource "aws_api_gateway_method" "get_task" {
  rest_api_id   = aws_api_gateway_rest_api.todo_api.id
  resource_id   = aws_api_gateway_resource.task_id.id
