# Lambda: Create Task

data "archive_file" "create_task" {
  type        = "zip"
  source_file = "${path.module}/lambda/create_task.py"
  output_path = "${path.module}/build/create_task.zip"
}

resource "aws_cloudwatch_log_group" "create_task_log" {
  name = "/aws/lambda/${aws_lambda_function.create_task.function_name}"
}

resource "aws_iam_role" "create_task_role" {
  name = "create_task_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Action = "sts:AssumeRole",
      Principal = { Service = "lambda.amazonaws.com" },
      Effect = "Allow"
    }]
  })
}

resource "aws_iam_role_policy" "create_task_policy" {
  name = "create_task_policy"
  role = aws_iam_role.create_task_role.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Action = ["dynamodb:PutItem"],
      Resource = aws_dynamodb_table.tasks.arn
    }]
  })
}

resource "aws_iam_role_policy_attachment" "create_task_basic" {
  role       = aws_iam_role.create_task_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "create_task" {
  function_name = "create_task"
  role          = aws_iam_role.create_task_role.arn
  handler       = "create_task.lambda_handler"
  runtime       = "python3.12"
  filename      = data.archive_file.create_task.output_path
  source_code_hash = data.archive_file.create_task.output_base64sha256
  environment {
    variables = {
      TABLE_NAME = var.table_name
    }
  }
  depends_on = [aws_cloudwatch_log_group.create_task_log]
}

resource "aws_lambda_permission" "create_task_apigw" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.create_task.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.todo_api.execution_arn}/*/*"
