import os
import json
import logging
import boto3
from botocore.exceptions import ClientError

logger = logging.getLogger()
logger.setLevel(logging.INFO)

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])

def lambda_handler(event, context):
    try:
        task_id = event.get('pathParameters', {}).get('id')
        if not task_id:
            return {"statusCode": 400, "headers": {"Content-Type": "application/json"}, "body": json.dumps({"error": "id path parameter required"})}
        body = json.loads(event.get('body', '{}'))
        update_expressions = []
        expression_attribute_values = {}
        allowed_fields = ['title', 'description', 'completed']
        for field in allowed_fields:
            if field in body:
                update_expressions.append(f"{field} = :{field}")
                expression_attribute_values[f":{field}"] = body[field]
        if not update_expressions:
            return {"statusCode": 400, "headers": {"Content-Type": "application/json"}, "body": json.dumps({"error": "No valid fields to update"})}
        update_expression = "SET " + ", ".join(update_expressions)
        response = table.update_item(
            Key={'id': task_id},
            UpdateExpression=update_expression,
            ExpressionAttributeValues=expression_attribute_values,
            ReturnValues="ALL_NEW"
        )
        item = response.get('Attributes')
        return {"statusCode": 200, "headers": {"Content-Type": "application/json"}, "body": json.dumps(item)}
    except ClientError as e:
        logger.error(e)
        return {"statusCode": 500, "headers": {"Content-Type": "application/json"}, "body": json.dumps({"error": "Internal server error"})}
    except Exception as e:
        logger.error(e)
        return {"statusCode": 500, "headers": {"Content-Type": "application/json"}, "body": json.dumps({"error": "Internal server error"})}

